        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        sites = s.get('sites') or []
        occupied = sum(max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites)
