def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    elements = [t.get('element') for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    total = sum(occ)
    if total <= 0:
        return 0.0
    amounts = {}
    for i in range(n):
        amounts[elements[i]] = amounts.get(elements[i], 0.0) + occ[i]
    weight = 0.0
    unlike = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and d <= 1.25 * (a + b):
                w = occ[i] * occ[j]
                weight += w
                if elements[i] != elements[j]:
                    unlike += w
    if weight <= 0:
        return 0.0
    expected = 1.0 - sum((v / total) ** 2 for v in amounts.values())
    return unlike / weight - expected

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    chi = [(props.get(t.get('element')) or {}).get('eneg') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    differences = [0.0 for t in sites]
    weights = [0.0 for t in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and chi[i] is not None and chi[j] is not None and d <= 1.25 * (a + b):
                weights[i] += occ[j]
                differences[i] += occ[j] * (chi[j] - chi[i])
    total = sum(occ[i] for i in range(n) if weights[i] > 0)
    if total <= 0:
        return 0.0
    square = sum(occ[i] * (differences[i] / weights[i]) ** 2 for i in range(n) if weights[i] > 0)
    return sqrt(max(0.0, square / total))

def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    value = 0.0
    for site in s.get('sites') or []:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        ionization = (props.get(site.get('element')) or {}).get('first_ionization_energy_eV')
        if ionization is not None and ionization > 0:
            total += o
            value += o * ionization
    return value / total if total > 0 else 0.0
